7	function mean(values) {
8	  if (!values.length) {
9	    return 0
10	  }
11	
12	  let total = 0
13	  for (let index = 0; index < values.length; index += 1) {
14	    total += values[index]
15	  }
16	  return total / values.length
17	}
18	
19	function variance(values) {
20	  if (!values.length) {
21	    return 0
22	  }
23	
24	  const average = mean(values)
25	  let total = 0
26	  for (let index = 0; index < values.length; index += 1) {
27	    const delta = values[index] - average
28	    total += delta * delta
29	  }
30	  return total / values.length
31	}
