48	export function pushSample(window, sample) {
49	  const now = sample.timestamp || Date.now()
50	  if (!window.startedAt) {
51	    window.startedAt = now
52	  }
53	  window.endedAt = now
54	  window.samples.push(sample)
55	
56	  if (window.samples.length > window.maxSamples) {
57	    window.samples.shift()
58	  }
