61	export function extractFeatures(window) {
62	  const samples = window.samples
63	  const magnitudes = []
64	  let peakG = 0
65	  let minG = 99
66	  let lowMotionCount = 0
67	
68	  for (let index = 0; index < samples.length; index += 1) {
69	    const currentMagnitude = magnitude(samples[index])
70	    magnitudes.push(currentMagnitude)
71	    peakG = Math.max(peakG, currentMagnitude)
72	    minG = Math.min(minG, currentMagnitude)
73	
74	    if (index > 0) {
75	      const previousMagnitude = magnitudes[index - 1]
76	      if (Math.abs(currentMagnitude - previousMagnitude) < 0.025) {
77	        lowMotionCount += 1
78	      }
79	    }
80	  }
81	
82	  const tailSize = Math.min(10, magnitudes.length)
83	  const tail = magnitudes.slice(magnitudes.length - tailSize)
84	  const first = samples[0] || {z: 1}
85	  const last = samples[samples.length - 1] || {z: 1}
86	  const durationMs = Math.max(
87	    window.endedAt - window.startedAt,
88	    samples.length > 1 ? (samples.length - 1) * 80 : 0
89	  )
90	
91	  return {
92	    peakG: peakG,
93	    minG: minG === 99 ? 0 : minG,
94	    variance: variance(magnitudes),
95	    postVariance: variance(tail),
96	    orientationChange: Math.abs(first.z - last.z),
97	    lowMotionRatio: samples.length > 1 ? lowMotionCount / (samples.length - 1) : 0,
98	    durationMs: durationMs,
99	    sampleCount: samples.length
100	  }
101	}
