134	export function createReplayEngine(callbacks) {
135	  let timer = null
136	
137	  function stop() {
138	    if (timer) {
139	      clearInterval(timer)
140	      timer = null
141	    }
142	  }
143	
144	  function start(scenarioId) {
145	    stop()
146	    let definition = SCENARIOS[0]
147	    for (let index = 0; index < SCENARIOS.length; index += 1) {
148	      if (SCENARIOS[index].id === scenarioId) {
149	        definition = SCENARIOS[index]
150	        break
151	      }
152	    }
153	
154	    let sampleIndex = 0
155	    if (callbacks.onStart) {
156	      callbacks.onStart(definition)
157	    }
158	
159	    timer = setInterval(function() {
160	      const sample = makeSample(definition.id, sampleIndex)
161	      if (callbacks.onSample) {
162	        callbacks.onSample(sample, sampleIndex + 1, definition.samples)
163	      }
164	      sampleIndex += 1
165	
166	      if (sampleIndex >= definition.samples) {
167	        stop()
168	        if (callbacks.onComplete) {
169	          callbacks.onComplete(definition)
170	        }
171	      }
172	    }, SAMPLE_INTERVAL_MS)
173	  }
174	
175	  return {
176	    start: start,
177	    stop: stop
178	  }
