161	<script>
162	import router from "@system.router"
163	import {withdrawEvent} from "../../common/event-machine.js"
164	import {loadSettings, updateEvent} from "../../common/storage.js"
165	
166	function pad(value) {
167	  return value < 10 ? "0" + value : String(value)
168	}
169	
170	function fullTimeLabel(event) {
171	  if (!event.createdAt) {
172	    return event.timeLabel
173	  }
174	  const date = new Date(event.createdAt)
175	  return (
176	    date.getFullYear() +
177	    "-" +
178	    pad(date.getMonth() + 1) +
179	    "-" +
180	    pad(date.getDate()) +
181	    " " +
182	    pad(date.getHours()) +
183	    ":" +
184	    pad(date.getMinutes()) +
185	    ":" +
186	    pad(date.getSeconds())
187	  )
188	}
189	
190	function statusClassFor(status) {
191	  if (status === "queued" || status === "withdrawal_queued") {
192	    return "status-queued"
193	  }
194	  if (status === "withdrawn") {
195	    return "status-withdrawn"
196	  }
197	  if (status === "cancelled") {
198	    return "status-cancelled"
199	  }
200	  return "status-sent"
201	}
202	
203	export default {
204	  private: {
205	    currentPage: 0,
206	    pageTitle: "事件概览",
207	    pageIndicator: "1 / 3",
208	    overviewTabClass: "page-tab-active",
209	    messageTabClass: "",
210	    timelineTabClass: "",
211	    typeLabel: "事件详情",
212	    statusLabel: "--",
213	    statusClass: "status-sent",
214	    timeLabel: "--",
215	    confidence: 0,
216	    locationLabel: "--",
217	    resultLabel: "--",
218	    reasons: [],
219	    peakG: "--",
220	    source: "--",
221	    timeline: [],
222	    contacts: [],
223	    hasMessage: false,
224	    showNoMessage: true,
225	    timelineEmpty: true,
226	    messageTitle: "",
227	    messageType: "",
228	    messageTime: "",
229	    messageLocation: "",
230	    messageConfidence: "",
231	    wearerStatus: "",
232	    deviceStatus: "",
233	    recipientSummary: "",
234	    deliveryText: "",
235	    canWithdraw: false,
236	    hasWithdrawal: false,
237	    withdrawalMessage: ""
238	  },
239	
240	  onShow() {
241	    const event = this.$app.$def.getCurrentEvent()
242	    if (!event) {
243	      router.back()
244	      return
245	    }
246	    this.showPage(0)
247	    this.renderEvent(event)
248	  },
249	
250	  renderEvent(event) {
251	    this.event = event
252	    this.typeLabel = event.typeLabel
253	    this.statusLabel = event.statusLabel
254	    this.statusClass = statusClassFor(event.status)
255	    this.timeLabel = fullTimeLabel(event)
256	    this.confidence = event.confidence
257	    this.locationLabel = event.locationLabel
258	    this.resultLabel = event.resultLabel
259	    this.reasons = event.reasons || []
260	    this.peakG = event.peakG
261	    this.source = event.source
262	    this.timeline = event.timeline || []
263	    this.timelineEmpty = this.timeline.length === 0
264	    this.contacts = event.contacts || []
265	    this.hasMessage = Boolean(event.message)
266	    this.showNoMessage = !this.hasMessage
267	    this.deliveryText =
268	      event.status === "queued" ? "待发送" : event.status === "cancelled" ? "未发送" : "已通知"
269	    this.canWithdraw = event.status === "sent"
270	    this.hasWithdrawal = Boolean(event.withdrawalMessage)
271	    this.withdrawalMessage = event.withdrawalMessage || ""
272	
273	    if (event.message) {
274	      this.messageTitle = event.message.title
275	      this.messageType = event.message.type
276	      this.messageTime = event.message.time
277	      this.messageLocation = event.message.location
278	      this.messageConfidence = event.message.confidence
279	      this.wearerStatus = event.message.wearerStatus
280	      this.deviceStatus = event.message.deviceStatus
281	      this.recipientSummary = event.message.recipients
282	    }
283	  },
284	
285	  showPage(pageIndex) {
286	    this.currentPage = pageIndex
287	    this.overviewTabClass = pageIndex === 0 ? "page-tab-active" : ""
288	    this.messageTabClass = pageIndex === 1 ? "page-tab-active" : ""
289	    this.timelineTabClass = pageIndex === 2 ? "page-tab-active" : ""
290	
291	    if (pageIndex === 0) {
292	      this.pageTitle = "事件概览"
293	    } else if (pageIndex === 1) {
294	      this.pageTitle = "求助信息"
295	    } else {
296	      this.pageTitle = "处理过程"
297	    }
298	    this.pageIndicator = pageIndex + 1 + " / 3"
299	    this.scrollToTop()
300	  },
301	
302	  previousPage() {
303	    if (this.currentPage > 0) {
304	      this.showPage(this.currentPage - 1)
305	    }
306	  },
307	
308	  nextPage() {
309	    if (this.currentPage < 2) {
310	      this.showPage(this.currentPage + 1)
311	    }
312	  },
313	
314	  scrollToTop() {
315	    const page = this
316	    setTimeout(function() {
317	      try {
318	        const detailScroll = page.$element("detailScroll")
319	        if (detailScroll) {
320	          detailScroll.scrollTo({
321	            top: 0,
322	            left: 0,
323	            behavior: "instant"
324	          })
325	        }
326	      } catch (error) {
327	        console.log("detail scroll reset skipped", error)
328	      }
329	    }, 0)
330	  },
331	
332	  withdraw() {
333	    const page = this
334	    if (!this.event || !this.canWithdraw) {
335	      return
336	    }
337	
338	    loadSettings(function(settings) {
339	      const updated = withdrawEvent(page.event, settings.demoOffline)
340	      updateEvent(updated, function() {
341	        page.$app.$def.setCurrentEvent(updated)
342	        page.renderEvent(updated)
343	      })
344	    })
345	  },
346	
347	  goBack() {
348	    router.back()
349	  }
350	}
351	</script>
